{
  "conversations": [
    {
      "title": "State my dietary restrictions",
      "lines": [
        { "speaker": "you", "text": "Hi." },
        { "speaker": "partner", "text": "Welcome." },
        { "speaker": "you", "text": "I'm vegan." },
        { "speaker": "partner", "text": "What does that mean?" },
        { "speaker": "you", "text": "No meat, fish, eggs, or dairy." },
        { "speaker": "you", "text": "No fish broth either.", "or": true },
        { "speaker": "partner", "text": "Got it." }
      ]
    },
    {
      "title": "Ask about hidden ingredients",
      "lines": [
        { "speaker": "you", "text": "Excuse me." },
        { "speaker": "partner", "text": "Yes?" },
        { "speaker": "you", "text": "Is this vegan?" },
        { "speaker": "partner", "text": "It has egg." },
        { "speaker": "partner", "text": "It's completely plant-based.", "or": true },
        { "speaker": "you", "text": "Does it have dashi in it?" },
        { "speaker": "partner", "text": "Yes, it uses fish broth." },
        { "speaker": "partner", "text": "No, it's vegetable broth.", "or": true },
        { "speaker": "you", "text": "Thank you." }
      ]
    },
    {
      "title": "Order vegan dishes",
      "lines": [
        { "speaker": "you", "text": "I'll take this one, please." },
        { "speaker": "partner", "text": "Coming right up." },
        { "speaker": "you", "text": "Can I get this without egg, please?", "or": true },
        { "speaker": "partner", "text": "Sure, we can do that." },
        { "speaker": "partner", "text": "Sorry, we can't remove it.", "or": true },
        { "speaker": "you", "text": "Thanks." }
      ]
    }
  ]
}
